    # tile contents are left intact; only the empty separator cells are filled.
    for color in set(counts) - {background}:
        for r in range(h):
            cols = [c for c in range(w) if out[r][c] == color]
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if out[r][c] == 0:
                        out[r][c] = color

        for c in range(w):
            rows = [r for r in range(h) if out[r][c] == color]
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    if out[r][c] == 0:
