def transform(grid):
    from collections import Counter

    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    # The repeated pattern colors are the less frequent colors; the dominant
    # colors form the background tiles and their borders.
    ranked = sorted(counts.values())
    cutoff = ranked[-2] if len(ranked) >= 2 else 0
    colors = [c for c, n in counts.items() if n < cutoff]

    for color in colors:
        for r in range(h):
            spots = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(spots, spots[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == 0:
                        out[r][c] = color
        for c in range(w):
            spots = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(spots, spots[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out
